11	const BASE_PREMIUM: Record<string, number> = {
12	  sword: 100,
13	  amulet: 60,
14	  staff: 80,
15	  potion: 40,
16	};
17	
18	const PROCESSING_FEE = 5;
19	const FIRST_INSURANCE_SURCHARGE = 0.1;
20	
21	const itemPremium = (item: { type: string }): number => {
22	  const base = BASE_PREMIUM[item.type];
23	  return base + base * FIRST_INSURANCE_SURCHARGE;
24	};
25	
26	const quotePremium = (items: { type: string }[]): number => {
27	  const itemsTotal = items.reduce((sum, item) => sum + itemPremium(item), 0);
28	  return Math.ceil(itemsTotal + PROCESSING_FEE);
29	};
30	
31	export const runScenario = (scenario: Scenario): { results: unknown[] } => {
32	  const results = scenario.steps.map((step) => ({
33	    premium: quotePremium(step.items),
34	  }));
35	  return { results };
36	};
